<?php
 namespace Pterodactyl\Services\Dezerx\Ai; use Throwable; use Illuminate\Support\Str; use Illuminate\Support\Facades\Log; use Illuminate\Support\Facades\Http; use Illuminate\Support\Facades\Cache; class ModelCatalog { private const TTL = 3600; private ?string $error = null; private const NOT_CHAT = ['embed', 'embedding', 'tts', 'whisper', 'audio', 'realtime', 'dall-e', 'image', 'imagen', 'veo', 'moderation', 'rerank', 'transcribe', 'search-', 'similarity', 'edit-', 'aqa', 'guard', '-live', 'lyria', 'nano-banana', 'computer-use', 'robotics', 'deep-research', 'sora', 'codex-mini']; public function for(string $provider, ?string $key, bool $fresh = false): array { if (($key === null || $key === '') && !Ai::keyless($provider)) { return $this->fallback($provider, null); } $key = $key ?? 'local'; $cacheKey = 'dezerx:ai-models:' . $provider . ':' . substr(hash('sha256', $key), 0, 16); if ($fresh) { Cache::forget($cacheKey); } $this->error = null; $models = Cache::remember($cacheKey, self::TTL, fn() => $this->fetch($provider, $key)); if ($models === []) { Cache::forget($cacheKey); return $this->fallback($provider, $this->error); } return ['models' => $models, 'live' => true, 'error' => null]; } private function fallback(string $provider, ?string $error): array { $default = Ai::defaultModel($provider); return ['models' => $default !== '' ? [$default] : [], 'live' => false, 'error' => $error]; } private function fetch(string $provider, string $key): array { try { $ids = $provider === 'anthropic' ? $this->anthropic($key) : $this->openAiCompatible($provider, $key); } catch (Throwable $e) { $this->error = class_basename($e) . ': ' . Str::limit($e->getMessage(), 160); Log::warning('Could not list AI models', ['provider' => $provider, 'exception' => $e::class, 'reason' => Str::limit($e->getMessage(), 500)]); return []; } $chat = array_values(array_filter($ids, $this->isChatModel(...))); if ($chat === [] && $ids !== []) { $this->error = 'The endpoint listed ' . count($ids) . ' models and none of them look like chat models.'; } rsort($chat); return array_slice($chat, 0, 60); } private function anthropic(string $key): array { $response = Http::withHeaders(['x-api-key' => $key, 'anthropic-version' => '2023-06-01'])->connectTimeout(5)->acceptJson()->timeout(15)->get('https://api.anthropic.com/v1/models', ['limit' => 100]); if ($response->failed()) { $this->error = 'The endpoint answered ' . $response->status() . '.'; return []; } return array_map(fn(array $model) => (string) ($model['id'] ?? ''), (array) ($response->json('data') ?? [])); } private function openAiCompatible(string $provider, string $key): array { $base = Ai::baseUrlFor($provider); $base = $base !== '' ? $base : 'https://api.openai.com/v1'; $response = Http::withToken($key)->connectTimeout(5)->acceptJson()->timeout(15)->get(rtrim($base, '/') . '/models'); if ($response->failed()) { $this->error = 'The endpoint answered ' . $response->status() . '.'; Log::warning('AI model list was refused', ['provider' => $provider, 'status' => $response->status(), 'body' => Str::limit($response->body(), 500)]); return []; } return array_map(fn(array $model) => str_replace('models/', '', (string) ($model['id'] ?? '')), (array) ($response->json('data') ?? [])); } private function isChatModel(string $id): bool { if ($id === '') { return false; } $lower = strtolower($id); foreach (self::NOT_CHAT as $needle) { if (str_contains($lower, $needle)) { return false; } } return true; } } 